package com.bank.rollout;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class DynamicRegionCounter {

    private static final Logger log = Logger.getLogger(DynamicRegionCounter.class.getName());
    private int[] parent;
    private int[] size;
    private boolean[] isLand;
    private int count;
    private int cols;
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;              // union by size
        size[ra] += size[rb];
        return true;
    }

    public List<Integer> numIslands2(int rows, int cols, int[][] positions) {
        this.cols = cols;
        parent = new int[rows * cols];
        size = new int[rows * cols];
        isLand = new boolean[rows * cols];
        count = 0;
        List<Integer> result = new ArrayList<>();
        for (int[] p : positions) {
            int idx = p[0] * cols + p[1];
            if (isLand[idx]) { result.add(count); continue; } // already land
            isLand[idx] = true;
            parent[idx] = idx; size[idx] = 1;
            count++;
            for (int[] d : DIRS) {
                int nr = p[0] + d[0], nc = p[1] + d[1];
                if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
                int nb = nr * cols + nc;
                if (isLand[nb] && union(idx, nb)) count--;
            }
            final int c = count;
            log.info(() -> "After activating (" + p[0] + "," + p[1] + ") regions=" + c);
            result.add(count);
        }
        return result;
    }
}
