package com.bank.rollout;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class DynamicRegionDemo {

    private static final Logger log = Logger.getLogger(DynamicRegionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Rollout Dynamic Region Counter");
        int[][] positions = {{0, 0}, {0, 1}, {1, 2}, {2, 1}};
        DynamicRegionCounter counter = new DynamicRegionCounter();
        log.info("Running counts: " + counter.numIslands2(3, 3, positions));
    }
}
